-- 222: coasters that came in with the new parks from the weekly review as
-- "operating" although their source says defunct, removed or standing but not
-- operating, with no closing date (Carter, 2026-11-24: "I think remove them
-- ... no need to show on site at all without sufficient info"). 40 coasters,
-- none ridden or ranked, and the 38 parks left empty by them (Beihai Park
-- loses both of its; Palace Playland keeps its other four).
-- Nothing is lost: open_items/open_raw keep every source record, and the
-- reviews below are marked "reject: no closing date (222)" so the weekly
-- refresh does not offer them again and they can be found if a date turns up.
-- Ids are the ones checked live on 2026-11-24; the guards keep a second run
-- (or a ride logged since) from touching anything.
INSERT OR REPLACE INTO open_reviews (kind, source, ref, coaster_id, decision, note, by, at) SELECT 'add', l.source, l.ref, 0, 'reject', 'no closing date (222)', 'migration', strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM open_links l WHERE l.coaster_id IN (SELECT id FROM coasters WHERE id IN (4014,4017,4020,4021,4023,4024,4025,4038,4041,4046,4053,4055,4058,4059,4060,4063,4065,4066,4071,4076,4077,4087,4090,4091,4095,4096,4098,4100,4101,4107,4108,4110,4111,4113,4022,4031,4032,4061,4086,4097) AND closed IS NULL AND id NOT IN (SELECT coaster_id FROM rankings) AND id NOT IN (SELECT coaster_id FROM rides WHERE coaster_id IS NOT NULL));
UPDATE open_reviews SET decision = 'reject', note = note || ' (no closing date, 222)' WHERE kind = 'park' AND decision = 'approve' AND note IN (SELECT park FROM coasters WHERE id IN (4014,4017,4020,4021,4023,4024,4025,4038,4041,4046,4053,4055,4058,4059,4060,4063,4065,4066,4071,4076,4077,4087,4090,4091,4095,4096,4098,4100,4101,4107,4108,4110,4111,4113,4022,4031,4032,4061,4086,4097) AND closed IS NULL AND id NOT IN (SELECT coaster_id FROM rankings) AND id NOT IN (SELECT coaster_id FROM rides WHERE coaster_id IS NOT NULL)) AND NOT EXISTS (SELECT 1 FROM coasters c WHERE c.park = open_reviews.note AND c.id NOT IN (4014,4017,4020,4021,4023,4024,4025,4038,4041,4046,4053,4055,4058,4059,4060,4063,4065,4066,4071,4076,4077,4087,4090,4091,4095,4096,4098,4100,4101,4107,4108,4110,4111,4113,4022,4031,4032,4061,4086,4097));
DELETE FROM open_facts WHERE coaster_id IN (SELECT id FROM coasters WHERE id IN (4014,4017,4020,4021,4023,4024,4025,4038,4041,4046,4053,4055,4058,4059,4060,4063,4065,4066,4071,4076,4077,4087,4090,4091,4095,4096,4098,4100,4101,4107,4108,4110,4111,4113,4022,4031,4032,4061,4086,4097) AND closed IS NULL AND id NOT IN (SELECT coaster_id FROM rankings) AND id NOT IN (SELECT coaster_id FROM rides WHERE coaster_id IS NOT NULL));
DELETE FROM open_links WHERE coaster_id IN (SELECT id FROM coasters WHERE id IN (4014,4017,4020,4021,4023,4024,4025,4038,4041,4046,4053,4055,4058,4059,4060,4063,4065,4066,4071,4076,4077,4087,4090,4091,4095,4096,4098,4100,4101,4107,4108,4110,4111,4113,4022,4031,4032,4061,4086,4097) AND closed IS NULL AND id NOT IN (SELECT coaster_id FROM rankings) AND id NOT IN (SELECT coaster_id FROM rides WHERE coaster_id IS NOT NULL));
DELETE FROM open_choices WHERE coaster_id IN (SELECT id FROM coasters WHERE id IN (4014,4017,4020,4021,4023,4024,4025,4038,4041,4046,4053,4055,4058,4059,4060,4063,4065,4066,4071,4076,4077,4087,4090,4091,4095,4096,4098,4100,4101,4107,4108,4110,4111,4113,4022,4031,4032,4061,4086,4097) AND closed IS NULL AND id NOT IN (SELECT coaster_id FROM rankings) AND id NOT IN (SELECT coaster_id FROM rides WHERE coaster_id IS NOT NULL));
DELETE FROM coaster_sources WHERE coaster_id IN (SELECT id FROM coasters WHERE id IN (4014,4017,4020,4021,4023,4024,4025,4038,4041,4046,4053,4055,4058,4059,4060,4063,4065,4066,4071,4076,4077,4087,4090,4091,4095,4096,4098,4100,4101,4107,4108,4110,4111,4113,4022,4031,4032,4061,4086,4097) AND closed IS NULL AND id NOT IN (SELECT coaster_id FROM rankings) AND id NOT IN (SELECT coaster_id FROM rides WHERE coaster_id IS NOT NULL));
DELETE FROM coaster_aliases WHERE coaster_id IN (SELECT id FROM coasters WHERE id IN (4014,4017,4020,4021,4023,4024,4025,4038,4041,4046,4053,4055,4058,4059,4060,4063,4065,4066,4071,4076,4077,4087,4090,4091,4095,4096,4098,4100,4101,4107,4108,4110,4111,4113,4022,4031,4032,4061,4086,4097) AND closed IS NULL AND id NOT IN (SELECT coaster_id FROM rankings) AND id NOT IN (SELECT coaster_id FROM rides WHERE coaster_id IS NOT NULL));
DELETE FROM clone_members WHERE coaster IN (SELECT id FROM coasters WHERE id IN (4014,4017,4020,4021,4023,4024,4025,4038,4041,4046,4053,4055,4058,4059,4060,4063,4065,4066,4071,4076,4077,4087,4090,4091,4095,4096,4098,4100,4101,4107,4108,4110,4111,4113,4022,4031,4032,4061,4086,4097) AND closed IS NULL AND id NOT IN (SELECT coaster_id FROM rankings) AND id NOT IN (SELECT coaster_id FROM rides WHERE coaster_id IS NOT NULL));
DELETE FROM same_ride WHERE coaster IN (SELECT id FROM coasters WHERE id IN (4014,4017,4020,4021,4023,4024,4025,4038,4041,4046,4053,4055,4058,4059,4060,4063,4065,4066,4071,4076,4077,4087,4090,4091,4095,4096,4098,4100,4101,4107,4108,4110,4111,4113,4022,4031,4032,4061,4086,4097) AND closed IS NULL AND id NOT IN (SELECT coaster_id FROM rankings) AND id NOT IN (SELECT coaster_id FROM rides WHERE coaster_id IS NOT NULL));
DELETE FROM activity WHERE kind = 'coaster_added' AND json_extract(detail, '$.id') IN (SELECT id FROM coasters WHERE id IN (4014,4017,4020,4021,4023,4024,4025,4038,4041,4046,4053,4055,4058,4059,4060,4063,4065,4066,4071,4076,4077,4087,4090,4091,4095,4096,4098,4100,4101,4107,4108,4110,4111,4113,4022,4031,4032,4061,4086,4097) AND closed IS NULL AND id NOT IN (SELECT coaster_id FROM rankings) AND id NOT IN (SELECT coaster_id FROM rides WHERE coaster_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS _gone_parks (name TEXT PRIMARY KEY);
INSERT OR IGNORE INTO _gone_parks SELECT DISTINCT park FROM coasters WHERE id IN (4014,4017,4020,4021,4023,4024,4025,4038,4041,4046,4053,4055,4058,4059,4060,4063,4065,4066,4071,4076,4077,4087,4090,4091,4095,4096,4098,4100,4101,4107,4108,4110,4111,4113,4022,4031,4032,4061,4086,4097) AND closed IS NULL AND id NOT IN (SELECT coaster_id FROM rankings) AND id NOT IN (SELECT coaster_id FROM rides WHERE coaster_id IS NOT NULL);
DELETE FROM coasters WHERE id IN (4014,4017,4020,4021,4023,4024,4025,4038,4041,4046,4053,4055,4058,4059,4060,4063,4065,4066,4071,4076,4077,4087,4090,4091,4095,4096,4098,4100,4101,4107,4108,4110,4111,4113,4022,4031,4032,4061,4086,4097) AND closed IS NULL AND id NOT IN (SELECT coaster_id FROM rankings) AND id NOT IN (SELECT coaster_id FROM rides WHERE coaster_id IS NOT NULL);
DELETE FROM parks WHERE name IN (SELECT name FROM _gone_parks) AND NOT EXISTS (SELECT 1 FROM coasters c WHERE c.park = parks.name);
DROP TABLE IF EXISTS _gone_parks;
